183	/// per-call value in **picoseconds**, and record it, clamping at
184	/// the histogram bounds — a suspend-inflated or wedged sample
185	/// must not panic a long run ([`warn_invalid`] flags it instead).
186	fn record_sample<B: Bench>(bench: &mut B, inner: u64, hist: &mut Histogram<u64>) {
187	    let start = minstant::Instant::now();
188	    for _ in 0..inner {
189	        black_box(bench.step());
190	    }
191	    let elapsed_ps = start.elapsed().as_nanos().saturating_mul(1000);
192	    hist.saturating_record(round_elapsed_ps(elapsed_ps, inner));
193	}
